import assert from 'node:assert/strict';
import { reduceEvents } from './receipt-report.js';

// null / array / non-object lines must throw
assert.throws(() => reduceEvents('null'), Error);
assert.throws(() => reduceEvents('[1,2]'), Error);
assert.throws(() => reduceEvents('42'), Error);
assert.throws(() => reduceEvents('"str"'), Error);

// invalid required fields must throw
assert.throws(() => reduceEvents('{"id":1,"job":"x","attempt":1,"seq":0,"type":"started"}'), Error);
assert.throws(() => reduceEvents('{"id":"","job":"x","attempt":1,"seq":0,"type":"started"}'), Error);
assert.throws(() => reduceEvents('{"id":"a","job":"","attempt":1,"seq":0,"type":"started"}'), Error);
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":0,"seq":0,"type":"started"}'), Error);
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1.5,"seq":0,"type":"started"}'), Error);
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1,"seq":-1,"type":"started"}'), Error);
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1,"seq":1.5,"type":"started"}'), Error);
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1,"seq":' + (Number.MAX_SAFE_INTEGER + 1) + ',"type":"started"}'), Error);
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1,"seq":0,"type":"done"}'), Error);

// CRLF and missing final newline
assert.deepEqual(reduceEvents('{"id":"a","job":"x","attempt":1,"seq":0,"type":"started"}\r\n{"id":"b","job":"x","attempt":1,"seq":5,"type":"succeeded"}'),
  { jobs: [{ job: 'x', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 5 }] }], duplicates: 0 });

// __proto__ id and unicode job
assert.deepEqual(reduceEvents('{"id":"__proto__","job":"j\u00e9\u0020x","attempt":1,"seq":0,"type":"started"}'),
  { jobs: [{ job: 'j\u00e9\u0020x', attempts: [{ attempt: 1, status: 'running', startedSeq: 0, finishedSeq: null }] }], duplicates: 0 });

// duplicate with extra fields counts
assert.equal(reduceEvents('{"id":"a","job":"x","attempt":1,"seq":0,"type":"started"}\n{"id":"a","job":"x","attempt":1,"seq":0,"type":"started","meta":1}').duplicates, 1);

// conflicting duplicate id throws
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1,"seq":0,"type":"started"}\n{"id":"a","job":"x","attempt":2,"seq":0,"type":"started"}'), Error);

// terminal seq equal to start seq throws
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1,"seq":0,"type":"started"}\n{"id":"b","job":"x","attempt":1,"seq":0,"type":"succeeded"}'), Error);

// two terminals for same (job,attempt) throws
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1,"seq":0,"type":"started"}\n{"id":"b","job":"x","attempt":1,"seq":2,"type":"succeeded"}\n{"id":"c","job":"x","attempt":1,"seq":3,"type":"failed"}'), Error);

// two starts for same (job,attempt) throws
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1,"seq":0,"type":"started"}\n{"id":"b","job":"x","attempt":1,"seq":1,"type":"started"}'), Error);

// orphan terminal throws
assert.throws(() => reduceEvents('{"id":"a","job":"x","attempt":1,"seq":5,"type":"failed"}'), Error);

// different attempts independent, overlapping seqs
assert.deepEqual(reduceEvents('{"id":"a","job":"x","attempt":1,"seq":0,"type":"started"}\n{"id":"b","job":"x","attempt":1,"seq":10,"type":"succeeded"}\n{"id":"c","job":"x","attempt":2,"seq":5,"type":"started"}\n{"id":"d","job":"x","attempt":2,"seq":6,"type":"failed"}'),
  { jobs: [{ job: 'x', attempts: [
    { attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 10 },
    { attempt: 2, status: 'failed', startedSeq: 5, finishedSeq: 6 },
  ] }], duplicates: 0 });

// job sort order (UTF-16 code units)
assert.deepEqual(reduceEvents('{"id":"a","job":"B","attempt":1,"seq":0,"type":"started"}\n{"id":"b","job":"a","attempt":1,"seq":0,"type":"started"}\n{"id":"c","job":"A","attempt":1,"seq":0,"type":"started"}'),
  { jobs: [{ job: 'A', attempts: [{ attempt: 1, status: 'running', startedSeq: 0, finishedSeq: null }] },
           { job: 'B', attempts: [{ attempt: 1, status: 'running', startedSeq: 0, finishedSeq: null }] },
           { job: 'a', attempts: [{ attempt: 1, status: 'running', startedSeq: 0, finishedSeq: null }] }], duplicates: 0 });

console.log('all contract checks passed');

