// Receipt reducer: build a small run-log report tool. Builtins only.

const TYPES = new Set(['started', 'succeeded', 'failed']);

function fail(message) {
  throw new Error(message);
}

function isNonemptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function isSafeInt(value, min) {
  return Number.isSafeInteger(value) && value >= min;
}

function requiredFields(event) {
  return {
    id: event.id,
    job: event.job,
    attempt: event.attempt,
    seq: event.seq,
    type: event.type,
  };
}

function sameRequiredFields(a, b) {
  return (
    a.id === b.id &&
    a.job === b.job &&
    a.attempt === b.attempt &&
    a.seq === b.seq &&
    a.type === b.type
  );
}

export function reduceEvents(text) {
  if (typeof text !== 'string') {
    fail('input must be a string');
  }

  const seen = new Map(); // id -> required fields
  let duplicates = 0;

  const lines = text.split(/\r\n|\n|\r/);
  for (const line of lines) {
    if (line.trim() === '') continue;

    let event;
    try {
      event = JSON.parse(line);
    } catch {
      fail('invalid JSON line');
    }
    if (event === null || typeof event !== 'object' || Array.isArray(event)) {
      fail('each line must be a JSON object');
    }

    const { id, job, attempt, seq, type } = event;
    if (!isNonemptyString(id)) fail('id must be a nonempty string');
    if (!isNonemptyString(job)) fail('job must be a nonempty string');
    if (!isSafeInt(attempt, 1)) fail('attempt must be a positive safe integer');
    if (!isSafeInt(seq, 0)) fail('seq must be a nonnegative safe integer');
    if (typeof type !== 'string' || !TYPES.has(type)) fail('type must be started, succeeded, or failed');

    const fields = requiredFields(event);
    const existing = seen.get(id);
    if (existing === undefined) {
      seen.set(id, fields);
    } else if (sameRequiredFields(existing, fields)) {
      duplicates += 1;
    } else {
      fail('conflicting duplicate id');
    }
  }

  const events = [...seen.values()];

  // Map (job, attempt) -> { start, terminal }
  const groups = new Map();
  const groupKey = (job, attempt) => job + '\u0000' + attempt;

  for (const event of events) {
    const key = groupKey(event.job, event.attempt);
    let group = groups.get(key);
    if (group === undefined) {
      group = { job: event.job, attempt: event.attempt, start: null, terminal: null };
      groups.set(key, group);
    }

    if (event.type === 'started') {
      if (group.start !== null) {
        fail('repeated start for (job, attempt) with different id');
      }
      group.start = event;
    } else {
      if (group.terminal !== null) {
        fail('contradictory terminals for (job, attempt)');
      }
      group.terminal = event;
    }
  }

  const jobs = new Map();
  for (const group of groups.values()) {
    if (group.start === null) {
      fail('orphan terminal event');
    }
    if (group.terminal !== null && group.terminal.seq <= group.start.seq) {
      fail('terminal seq must be strictly greater than start seq');
    }

    let jobEntry = jobs.get(group.job);
    if (jobEntry === undefined) {
      jobEntry = { job: group.job, attempts: [] };
      jobs.set(group.job, jobEntry);
    }
    jobEntry.attempts.push({
      attempt: group.attempt,
      status: group.terminal === null ? 'running' : group.terminal.type,
      startedSeq: group.start.seq,
      finishedSeq: group.terminal === null ? null : group.terminal.seq,
    });
  }

  const jobList = [...jobs.values()];
  jobList.sort((a, b) => (a.job < b.job ? -1 : a.job > b.job ? 1 : 0));
  for (const job of jobList) {
    job.attempts.sort((a, b) => a.attempt - b.attempt);
  }

  return { jobs: jobList, duplicates };
}

import { readFileSync } from 'node:fs';

function isMainModule() {
  if (typeof process === 'undefined' || !process.argv || !process.argv[1]) return false;
  try {
    const entry = new URL(import.meta.url).pathname;
    return process.argv[1] === entry;
  } catch {
    return false;
  }
}

if (isMainModule()) {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    process.stderr.write('usage: node receipt-report.js LOGFILE\n');
    process.exit(2);
  }
  let text;
  try {
    text = readFileSync(args[0], 'utf8');
  } catch (err) {
    process.stderr.write(`cannot read ${args[0]}: ${err.message}\n`);
    process.exit(2);
  }
  try {
    const report = reduceEvents(text);
    process.stdout.write(JSON.stringify(report) + '\n');
    process.exit(0);
  } catch (err) {
    process.stderr.write(`invalid events: ${err.message}\n`);
    process.exit(2);
  }
}

